1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Damage {
18	  itemType: string;
19	  amount: number;
20	}
21	
22	export interface ClaimStep {
23	  op: "claim";
24	  policy: number;
25	  incident: { cause: string; damages: Damage[] };
26	}
27	
28	export type Step = QuoteStep | ClaimStep;
29	
30	export interface Scenario {
31	  customer: Customer;
32	  steps: Step[];
33	}
34	
35	export type StepResult = { premium: number } | { payout: number; remainingCap: number };
36	
37	export interface ScenarioResult {
38	  results: StepResult[];
39	}
40	
41	const PROCESSING_FEE = 5;
42	
43	const FIRST_INSURANCE_PERCENT = 10;
44	
45	const BASE_PREMIUMS: Record<string, number> = {
46	  sword: 100,
47	  amulet: 60,
48	  staff: 80,
49	  potion: 40,
50	  rune: 25,
51	  moonstone: 25,
52	};
53	
54	const BLOCK_SIZE = 3;
55	const BLOCK_BASE_PREMIUM = 60;
56	
57	const countByType = (items: Item[]): Map<string, number> => {
58	  const counts = new Map<string, number>();
59	  for (const item of items) counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
60	
61	  return counts;
62	};
63	
64	const basePremiumForType = (type: string, count: number): number =>
65	  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * BASE_PREMIUMS[type];
66	
67	const policyBasePremium = (items: Item[]): number =>
68	  [...countByType(items)]
69	    .map(([type, count]) => basePremiumForType(type, count))
70	    .reduce((total, premium) => total + premium, 0);
71	
72	const CURSE_PERCENT = 50;
73	
74	// Percentages MUST go through this helper. Multiplying first and dividing by
75	// 100 afterwards keeps the arithmetic drift-free; the tempting `amount * 0.5`
76	// (or `* 1.1`) introduces binary-fraction error — 100 * 1.1 yields
77	// 110.00000000000001 — and since the spec rounds premiums UP at the very end
78	// that drift becomes a whole extra G.
79	const percentOf = (amount: number, percent: number): number => (amount * percent) / 100;
80	
81	const HIGH_ENCHANTMENT_PERCENT = 30;
82	const HIGH_ENCHANTMENT_THRESHOLD = 5;
83	
84	// Each item-level surcharge is "a percentage of this item's base premium, or
85	// nothing at all", so the condition is the only part that varies.
86	const percentOfWhen = (applies: boolean, amount: number, percent: number): number =>
87	  applies ? percentOf(amount, percent) : 0;
88	
89	const itemSurcharge = (item: Item): number => {
90	  const base = BASE_PREMIUMS[item.type];
91	  const curseSurcharge = percentOfWhen(item.cursed === true, base, CURSE_PERCENT);
92	  const highEnchantmentSurcharge = percentOfWhen(
93	    (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
94	    base,
95	    HIGH_ENCHANTMENT_PERCENT,
96	  );
97	
98	  return curseSurcharge + highEnchantmentSurcharge;
99	};
100	
101	const itemSurcharges = (items: Item[]): number =>
102	  items.reduce((total, item) => total + itemSurcharge(item), 0);
103	
104	// Every modifier is a percentage of a base premium, and they are SUMMED rather
105	// than compounded: the spec's worked example reads
106	// "100 G base + 50 G curse + 10 G first insurance = 160 G + 5 G fee = 165 G",
107	// so the first-insurance 10 % is taken on the policy base, not on the
108	// curse-inflated amount.
109	const LOYALTY_PERCENT = 20;
110	const LOYALTY_THRESHOLD_YEARS = 2;
111	
112	const quote = ({ items }: QuoteStep, customer: Customer): StepResult => {
113	  const policyBase = policyBasePremium(items);
114	  const firstInsurance = percentOf(policyBase, FIRST_INSURANCE_PERCENT);
115	  const loyaltyDiscount = percentOfWhen(
116	    customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS,
117	    policyBase,
118	    LOYALTY_PERCENT,
119	  );
120	  const total =
121	    policyBase + itemSurcharges(items) + firstInsurance - loyaltyDiscount + PROCESSING_FEE;
122	
123	  return { premium: Math.ceil(total) };
124	};
125	
126	export const runScenario = (scenario: Scenario): ScenarioResult => ({
127	  // Only quote steps are exercised so far; claim dispatch arrives with its first test.
128	  results: scenario.steps.map((step) => quote(step as QuoteStep, scenario.customer)),
129	});
